#ifndef __KERNEL_APODIZATION_H__
#define __KERNEL_APODIZATION_H__

#include <adf.h>
#include <kernels.hpp>

namespace us {
namespace L1 {

// declare param
template <class T>
struct para_Apodization {
    int iter_line;
    int iter_element;
    int iter_seg;
    int num_line;
    int num_element;
    int num_seg;
    int num_dep_seg; // = num_depth / num_seg = 512
    T f_num;
    T tileVApo_x;
    T tileVApo_z;
    T ref_point_x;
    T ref_point_z;
    void print() {
        printf("apo: <%d/%d lines, %d/%d elements, %d/%d segments>\n", iter_line, num_line, iter_element, num_element,
               iter_seg, num_seg);
    }
    void update() {
        if (iter_seg != num_seg - 1)
            iter_seg++;
        else {
            iter_seg = 0;
            if (iter_element != num_element - 1)
                iter_element++;
            else {
                iter_element = 0;
                iter_line++;
            }
        }
    }
};

