#include <adf.h>
#include <kernels.hpp>

namespace us {
namespace L1 {

using namespace adf;

struct para_foc_t {
    int32 iter_line;
    int32 iter_element;
    int32 iter_seg;
    int32 num_line;
    int32 num_element;
    int32 num_seg;
    para_foc_t(int32 line, int32 element, int32 seg) {
        iter_line = 0;
        iter_element = 0;
        iter_seg = 0;
        num_line = line;
        num_element = element;
        num_seg = seg;
    }
    void print() {
        printf("foc: <%d/%d lines, %d/%d elements, %d/%d segments>\n", iter_line, num_line, iter_element, num_element,
               iter_seg, num_seg);
    }
    int allZero() { return iter_line | iter_element | iter_seg; }
    void update() {
        if (iter_seg != num_seg - 1)
            iter_seg++;
        else {
            iter_seg = 0;
            if (iter_element != num_element - 1)
                iter_element++;
            else {
                iter_element = 0;
                iter_line++;
            }
        }
    }
};

