39	    focusing_graph(double kernel_ratio = KERNEL_RATIO) {
40	        //	kernel
41	        focusing_diffSVKernel1 = adf::kernel::create(us::L1::diffSV<T, LENGTH_, INCREMENT_VECTOR_, SIMD_DEPTH_>);
42	        focusing_diffSVKernel2 = adf::kernel::create(us::L1::diffSV<T, LENGTH_, INCREMENT_VECTOR_, SIMD_DEPTH_>);
43	        focusing_squareVKernel1 = adf::kernel::create(us::L1::squareV<T, LENGTH_, INCREMENT_VECTOR_, SIMD_DEPTH_>);
44	        focusing_squareVKernel2 = adf::kernel::create(us::L1::squareV<T, LENGTH_, INCREMENT_VECTOR_, SIMD_DEPTH_>);
45	        focusing_sumVVKernel = adf::kernel::create(us::L1::sumVV<T, LENGTH_, INCREMENT_VECTOR_, SIMD_DEPTH_>);
46	        focusing_sqrtVKernel = adf::kernel::create(us::L1::sqrtV<T, LENGTH_, INCREMENT_VECTOR_, SIMD_DEPTH_>);
47	
48	        adf::source(focusing_diffSVKernel1) = "diffSV/diffSV.cpp";
49	        adf::source(focusing_diffSVKernel2) = "diffSV/diffSV.cpp";
50	        adf::source(focusing_squareVKernel1) = "squareV/squareV.cpp";
51	        adf::source(focusing_squareVKernel2) = "squareV/squareV.cpp";
52	        adf::source(focusing_sumVVKernel) = "sumVV/sumVV.cpp";
53	        adf::source(focusing_sqrtVKernel) = "sqrtV/sqrtV.cpp";
54	
55	        // diffSV1
56	        adf::connect<>(apo_ref_0, focusing_diffSVKernel1.in[0]);
57	        adf::connect<>(xdc_def_0, focusing_diffSVKernel1.in[1]);
58	
59	        adf::dimensions(focusing_diffSVKernel1.in[0]) = {DIM_VECTOR_};
60	        adf::dimensions(focusing_diffSVKernel1.in[1]) = {DIM_VECTOR_};
61	        adf::dimensions(focusing_diffSVKernel1.out[0]) = {DIM_VECTOR_};
62	
63	        // diffSV2
64	        adf::connect<>(apo_ref_1, focusing_diffSVKernel2.in[0]);
65	        adf::connect<>(xdc_def_1, focusing_diffSVKernel2.in[1]);
66	
67	        adf::dimensions(focusing_diffSVKernel2.in[0]) = {DIM_VECTOR_};
68	        adf::dimensions(focusing_diffSVKernel2.in[1]) = {DIM_VECTOR_};
69	        adf::dimensions(focusing_diffSVKernel2.out[0]) = {DIM_VECTOR_};
70	
71	        // squareV1
72	        adf::connect<>(focusing_diffSVKernel1.out[0], focusing_squareVKernel1.in[0]);
73	
74	        adf::dimensions(focusing_squareVKernel1.in[0]) = {DIM_VECTOR_};
75	        adf::dimensions(focusing_squareVKernel1.out[0]) = {DIM_VECTOR_};
76	
77	        // squareV2
78	        adf::connect<>(focusing_diffSVKernel2.out[0], focusing_squareVKernel2.in[0]);
79	
80	        adf::dimensions(focusing_squareVKernel2.in[0]) = {DIM_VECTOR_};
81	        adf::dimensions(focusing_squareVKernel2.out[0]) = {DIM_VECTOR_};
82	
83	        // sumVV
84	        adf::connect<>(focusing_squareVKernel1.out[0], focusing_sumVVKernel.in[0]);
